let category="Все";const $=s=>document.querySelector(s),appsEl=$("#apps"),search=$("#search");
const classify=x=>{
 const s=(String(x.appName||"")+" "+String(x.appDescription||"")).toLowerCase();
 if(/банк|сбер|т-банк|альфа|втб|тинькофф|газпромбанк|райффайзен|россельхозбанк|почта банк|совкомбанк|сберkids/.test(s))return"Банки";
 if(/game|игр|minecraft|terraria|brawl|roblox|standoff|genshin|pubg|clash|subway surfers|among us|geometry dash|монополия|шахмат|пазл|arcade/.test(s))return"Игры";
 if(/instagram|инстаграм|вконтакте|вк мессенджер|telegram|телеграм|whatsapp|tiktok|тикток|snapchat|facebook|threads|discord|соцсет|messenger/.test(s))return"Соцсети";
 if(/photo|фото|camera|камера|video|видео|reels|vsco|instories|lightroom|capcut|съёмк|редактор фото|videostar|leica|opencam|artist.ai|picsart/.test(s))return"Фото и видео";
 if(/music|музык|soundcloud|spotify|djay|fl studio|audio|плеер|песн|радио|shazam/.test(s))return"Музыка";
 if(/utility|утилит|vpn|password|парол|file manager|documents|scanner|сканер|trollstore|esign|scarlet|fonts|шрифт|переводчик|калькулятор|calendar|календарь/.test(s))return"Утилиты";
 if(/service|сервис|chatgpt|openai|ai |искусственн|браузер|почта|почтов|карты|maps|такси|доставка|погода|облако|cloud|подписк|покупк|финанс|money pro/.test(s))return"Сервисы";
 return"Приложения";
};
function esc(s){return String(s||"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}
function render(){const q=search.value.trim().toLowerCase();let shown=items.filter(x=>(category==="Все"||classify(x)===category)&&[x.appName,x.appVersion,x.appDescription].join(" ").toLowerCase().includes(q));const sortOrder=$("#sortOrder")?.value||"newest";if(sortOrder==="newest")shown.reverse();else shown.sort((a,b)=>a.appName.trim().localeCompare(b.appName.trim(),"ru"));$("#count").textContent=shown.length+" "+(category==="Все"?"приложений":category==="Банки"?"банковских приложений":category==="Игры"?"игр":category==="Соцсети"?"социальных приложений":category==="Фото и видео"?"приложений для фото и видео":category==="Музыка"?"музыкальных приложений":category==="Утилиты"?"утилит":category==="Сервисы"?"сервисов":"приложений");$("#listTitle").textContent=category;appsEl.innerHTML=shown.length?shown.map((x,i)=>`<article class="app app-clickable" tabindex="0" role="button" data-app-index="${items.indexOf(x)}" aria-label="Подробнее о ${esc(x.appName.trim())}"><img class="app-image" src="${esc(x.appImage||"icon.png")}" alt="" loading="lazy" onerror="this.onerror=null;this.src='icon.png'"><div class="app-info"><h3>${esc(x.appName.trim())}</h3><p class="app-meta"><span class="app-published">${esc(x.appDate||"Дата не указана")}</span><span class="meta-sep">·</span><span>${esc((x.appVersion||"").split("|")[0].trim()||"Версия не указана")}</span><span class="meta-sep">·</span><span>${esc(((x.appVersion||"").split("|")[1]||"").trim()||"Размер не указан")}</span></p></div><button class="download" type="button" data-open-app="${items.indexOf(x)}">Установить </button></article>`).join(""):`<div class="empty">Ничего не найдено</div>`;
appsEl.querySelectorAll('[data-app-index]').forEach(card=>{const open=()=>openAppDetails(items[Number(card.dataset.appIndex)]);card.addEventListener('click',e=>{if(e.target.closest('a'))return;open()});card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}})});}
document.querySelectorAll("[data-category]").forEach(btn=>btn.addEventListener("click",()=>{category=btn.dataset.category;document.querySelectorAll("[data-category]").forEach(b=>{const active=b.dataset.category===category;b.classList.toggle("active",active);b.setAttribute("aria-pressed",String(active))});render()}));
search.addEventListener("input",render);document.querySelector("#sortOrder")?.addEventListener("change",render);
const root=document.documentElement;root.dataset.theme="dark";try{localStorage.setItem("ipaworld-theme","dark")}catch(e){}
const menuBtn=$("#menuBtn"),siteMenu=$("#siteMenu"),menuBackdrop=$("#menuBackdrop");
function openMenu(){siteMenu.classList.add("open");siteMenu.setAttribute("aria-hidden","false");menuBtn.setAttribute("aria-expanded","true");menuBackdrop.hidden=false;document.body.classList.add("no-scroll")}
function closeMenu(){siteMenu.classList.remove("open");siteMenu.setAttribute("aria-hidden","true");menuBtn.setAttribute("aria-expanded","false");menuBackdrop.hidden=true;document.body.classList.remove("no-scroll")}
menuBtn.onclick=()=>siteMenu.classList.contains("open")?closeMenu():openMenu();$("#closeMenu").onclick=closeMenu;menuBackdrop.onclick=closeMenu;document.addEventListener("keydown",e=>{if(e.key==="Escape")closeMenu()});
document.querySelectorAll("[data-menu-action]").forEach(btn=>btn.addEventListener("click",()=>{const action=btn.dataset.menuAction;closeMenu();if(action==="install")$("#installDialog").showModal();else if(action==="profile")$("#installDialog").showModal()}));$("#installBtn").onclick=()=>$("#installDialog").showModal();$("#profileNav").onclick=()=>$("#installDialog").showModal();$("#closeDialog").onclick=()=>$("#installDialog").close();

$("#showAll").onclick=()=>$("#apps").scrollIntoView({behavior:"smooth"});$("#filterBtn").onclick=()=>document.querySelector(".tabs").scrollIntoView({behavior:"smooth"});$("#categoriesNav").onclick=()=>document.querySelector(".tabs").scrollIntoView({behavior:"smooth"});$("#searchNav").onclick=()=>{search.focus();window.scrollTo({top:0,behavior:"smooth"})};$("#homeNav").onclick=()=>window.scrollTo({top:0,behavior:"smooth"});
render();
// Детальная карточка приложения — открывается по нажатию на карточку каталога.
const appDialog=document.querySelector('#appDialog');
function openAppDetails(x){
 if(!x)return;
 document.querySelector('#detailImage').src=x.appImage||'icon.png';
 document.querySelector('#detailTitle').textContent=(x.appName||'').trim();
 document.querySelector('#detailMeta').textContent=(x.appVersion||'Версия не указана').replace(/\s*\|\s*/g,' · ');
 const description=document.querySelector('#detailDescription');
 description.textContent=(x.appDescription||'Описание для этого приложения пока не добавлено').replace(/▎/g,'').split('\n').map(s=>s.trim()).filter(Boolean).join('\n');
 const botLink=document.querySelector('#detailBot');
 botLink.href='https://t.me/bbarne77';
 botLink.setAttribute('aria-label','Установить '+(x.appName||'приложение').trim()+' через Telegram');
 appDialog.showModal();
}
document.querySelector('#closeAppDialog').addEventListener('click',()=>appDialog.close());
appDialog.addEventListener('click',e=>{if(e.target===appDialog)appDialog.close()});
